/**
 * Public data layer. UI and logic import from here, never from the
 * individual files, so datasets can be swapped (API, JSON) in one place.
 *
 * `ANALOGS` is generated by `tools/discover.mjs` and committed as
 * `discovered.js`, so the static site works offline and every number has a
 * provenance trail back to a public scientific dataset.
 */
export { FACTORS } from './factors.js';
export { TARGETS } from './targets.js';
export { DISCOVERY, ANALOGS } from './discovered.js';
export { PRESETS } from './presets.js';
export { nonReplicableFor, environmentFor } from './planetary.js';

import { TARGETS } from './targets.js';
import { DISCOVERY, ANALOGS } from './discovered.js';

export const targetOf = (id) => TARGETS.find((t) => t.id === id);
export const analogOf = (id) => ANALOGS.find((a) => a.id === id);
export const targetsFor = (body) => TARGETS.filter((t) => t.body === body);

/** Snapshot header: generation time, grid size and the sources used. */
export const discoveryMeta = () => ({
  generatedAt: DISCOVERY.generatedAt,
  engineVersion: DISCOVERY.engineVersion,
  configVersion: DISCOVERY.configVersion,
  grid: DISCOVERY.grid,
  shortlist: DISCOVERY.shortlist,
  sources: DISCOVERY.sources
});

/** Look up the dataset record for a candidate's `sourceIds` entry. */
export const discoverySource = (id) =>
  (DISCOVERY.sources || []).find((source) => source.id === id) || null;
